using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Security.Cryptography;using System.Web.Script.Serialization;
internal static class NativeProductPlanRegression {
    static readonly JavaScriptSerializer Json=new JavaScriptSerializer();static string Config,Owner;static int checks;
