    static Dictionary<string,object> Document(string nonce){string code="console.log('fixed')";return new Dictionary<string,object>{{"contract","verification-native-plan/v1"},{"plan_id",new string('a',64)},{"attempt_id",nonce},{"owner_root",Owner},{"attempt_root",Path.Combine(Owner,"runs",nonce)},{"node_path",Path.Combine(Config,"sf-user","bin","verification","node.exe")},{"node_sha256","3602f2bb1a10f2cbab4c36886218a33c1ab3db87290e73b033c46c77147d0237"},{"daemon_path",Path.Combine(Config,"sf-user","bin","specforged.exe")},{"daemon_sha256",new string('b',64)},{"kind","node-inline"},{"entry",null},{"inline_source",code},{"argv",new[]{"--no-addons","--preserve-symlinks","--preserve-symlinks-main","-e",code}},{"files",new object[0]},{"profile","windows-lpac-node-single-process-readonly/v1"},{"wall_ms",120000},{"memory_bytes",1073741824},{"process_limit",1},{"output_bytes",1048576}};}
