    static void Rejected(string label,Action<Dictionary<string,object>> mutate){string nonce=Guid.NewGuid().ToString("N");var document=Document(nonce);mutate(document);string file=Save(document,nonce);bool rejected=false;try{LpacProductionPlan.Read(file,Hash(file));}catch{rejected=true;}Check(rejected,label);}
    static string[] Parse(string command){int count;IntPtr args=CommandLineToArgvW(command,out count);if(args==IntPtr.Zero)throw new Exception("ARGV_PARSE");try{var values=new string[count];for(int i=0;i<count;i++)values[i]=Marshal.PtrToStringUni(Marshal.ReadIntPtr(args,i*IntPtr.Size));return values;}finally{LocalFree(args);}}
    internal static int Main(){
