        string nonce=Guid.NewGuid().ToString("N"),file=Save(Document(nonce),nonce);var plan=LpacProductionPlan.Read(file,Hash(file));Check(plan.PlanId==new string('a',64)&&plan.WallMs==120000,"valid schema");Check(Parse(plan.CommandLine()).SequenceEqual(new[]{plan.NodePath}.Concat(plan.Argv)),"argv roundtrip");
