        bool badHash=false;try{LpacProductionPlan.Read(file,new string('0',64));}catch{badHash=true;}Check(badHash,"config hash mismatch");
        string source=Path.Combine(Owner,"input",plan.PlanId);Directory.CreateDirectory(source);string output=Path.Combine(root,"input-copy");Directory.CreateDirectory(output);plan.CopyInputs(output);Check(File.ReadAllText(Path.Combine(output,plan.ScriptName))==plan.InlineSource,"frozen inline exact bytes");File.WriteAllText(Path.Combine(source,"extra.txt"),"owned synthetic extra");bool extra=false;try{plan.CopyInputs(Path.Combine(root,"not-created"));}catch{extra=true;}Check(extra,"complete input set");
        Console.WriteLine(Json.Serialize(new{utc=DateTime.UtcNow.ToString("o"),fixture=root,checks=checks,profile_created=false,application_executed=false,inner_exit_code=0}));return 0;
    }
    [DllImport("shell32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr CommandLineToArgvW(string command,out int count);
    [DllImport("kernel32.dll")]static extern IntPtr LocalFree(IntPtr memory);
